"""Cross-check the Narayana refinement against the Catalan numbers and print
the valley-distribution triangle of Dyck lower endpoints.

For each semilength n we generate all Dyck paths, tabulate how many have each
valley count, and confirm the row sums equal the Catalan numbers 1,1,2,5,14,...
"""
from __future__ import annotations
from math import comb
from typing import Dict, List, Tuple


def catalan(n: int) -> int:
    return comb(2 * n, n) // (n + 1)


def dyck_paths(n: int) -> List[Tuple[int, ...]]:
    out: List[Tuple[int, ...]] = []
    path: List[int] = []

    def go(h: int, u: int, d: int) -> None:
        if u == 0 and d == 0:
            out.append(tuple(path)); return
        if u > 0:
            path.append(1); go(h + 1, u - 1, d); path.pop()
        if d > 0 and h > 0:
            path.append(-1); go(h - 1, u, d - 1); path.pop()

    go(0, n, n)
    return out


def valleys(path: Tuple[int, ...]) -> int:
    return sum(1 for a, b in zip(path, path[1:]) if a == -1 and b == 1)


def valley_triangle(max_n: int = 8) -> None:
    for n in range(1, max_n + 1):
        hist: Dict[int, int] = {}
        for p in dyck_paths(n):
            k = valleys(p)
            hist[k] = hist.get(k, 0) + 1
        row = [hist.get(k, 0) for k in range(0, n)]
        total = sum(row)
        cells = " ".join(f"{v:>4}" for v in row)
        print(f"n={n:<2} | {cells}   sum={total}  C_{n}={catalan(n)}  "
              f"{'OK' if total == catalan(n) else 'MISMATCH'}")


if __name__ == "__main__":
    valley_triangle(8)

