function IntervalHistogram(n, covers):
  hist <- empty map
  for each Dyck path x of semilength n:
    seen <- {x}; stack <- [x]
    while stack nonempty:
      cur <- pop(stack)
      for y in covers[cur]:
        if y not in seen: add y to seen; push y
    k <- valleys(x)
    hist[k] <- hist[k] + |seen|
  return hist

